	[5191]={ name="アステウス", type=5, mon_type=6, skill_list={5191,519101,519104}, passive_skill_list={519180,519183,300001}, skill_show_list={519180,519190,519183,519186,5191,519101,519104}, model="6317", head="monsterHead/mon_head_6317.png", color=4, hero_type=3, ele_type=0, stagger_voice=2, shadow_head="monsterShadow/mon_shadow_6317.png", show_Modelld="6317", win_voice=0, fail_voice=0, boss_head="monsterArchives/mon_archives_normal_6317.png", record_head="arts/ui/icon/monsterRecord/6317.png", weak_point={5,4}, hit_stun=1360, hit_stun_recover={0,0}, hit_stun_effect=519186, race=4, location=3, hp_section={}, describe="本体は第十二位の使徒級ヒュガルであり、「百年戦争」の後、タイノ星へと逃亡して静養に入った。長きにわたる潜伏の時の流れの中で、新たな野心を徐々に膨らませ、もはやヒュガルという種族的立場に甘んじることなく、世界の法則そのものから解き放たれることを誓う。そのために自らの封禁物を分裂させ、人類の支配を補助し、未知なる事象への信仰を利用して「喚星教義」を打ち立て、人類を導いて自らの傀儡国家を築かせた。そして血肉と養分を供給させることで、世界の法則を無視し得る全く新しい「神国」を創造しようとしたのである。", hero_tid=0, editor_skill={5191,519101,519104}
},
